    # Additional restriction: if we defected in the last two rounds, require higher reputation
    last_two = my_history[-2:] if len(my_history) >= 2 else []
    if any(action == 'defect' for (action, _) in last_two):
        return recipient_reputation > max(threshold, 0.3)
    else:
        return recipient_reputation > threshold

